 94	func (r *Reporter) loadState() error {
 95		data, err := os.ReadFile(r.path)
 96		if err != nil && !os.IsNotExist(err) {
 97			return fmt.Errorf("reading telemetry state: %w", err)
 98		}
 99	
100		needsSave := os.IsNotExist(err)
101		if !needsSave {
102			if err := json.Unmarshal(data, &r.state); err != nil {
103				r.logger.Warnf("invalid telemetry state, creating a new anonymous ID: %v", err)
104				r.state = state{}
105				needsSave = true
106			}
107		}
108	
109		if _, err := uuid.FromString(r.state.UUID); err != nil {
110			if !needsSave {
111				r.logger.Warn("invalid telemetry UUID, creating a new anonymous ID")
112			}
113			id, err := uuid.NewV4()
114			if err != nil {
115				return fmt.Errorf("generating telemetry ID: %w", err)
116			}
117			r.state.UUID = id.String()
118			needsSave = true
119		}
120		if r.state.Version != schemaVersion {
121			r.state.Version = schemaVersion
122			needsSave = true
123		}
124		if _, err := time.Parse(time.RFC3339, r.state.LastTimestamp); err != nil {
125			if !needsSave {
126				r.logger.Warn("invalid telemetry timestamp, resetting report time")
127			}
128			r.state.LastTimestamp = time.Time{}.UTC().Format(time.RFC3339)
129			needsSave = true
130		}
131		if needsSave {
132			if err := writeState(r.path, r.state); err != nil {
133				return fmt.Errorf("writing telemetry state: %w", err)
134			}
135		}
136		return nil
137	}
