139	func writeState(path string, s state) error {
140		data, err := json.MarshalIndent(s, "", "  ")
141		if err != nil {
142			return err
143		}
144		data = append(data, '\n')
145	
146		file, err := os.CreateTemp(filepath.Dir(path), ".telemetry-*.json")
147		if err != nil {
148			return err
149		}
150		defer os.Remove(file.Name())
151		if _, err := file.Write(data); err != nil {
152			_ = file.Close()
153			return err
154		}
155		if err := file.Close(); err != nil {
156			return err
157		}
158		return os.Rename(file.Name(), path)
159	}
