173		var retryAfter time.Time
174		for {
175			r.mu.Lock()
176			last, _ := time.Parse(time.RFC3339, r.state.LastTimestamp)
177			r.mu.Unlock()
178			due := last.Add(pingInterval)
179			if due.Before(retryAfter) {
180				due = retryAfter
181			}
182			wait := time.Until(due)
