184				wait = 0
185			}
186			timer := time.NewTimer(wait)
187			select {
188			case <-ctx.Done():
189				timer.Stop()
190				return
191			case <-timer.C:
192			}
193			if ctx.Err() != nil {
194				return
195			}
196			_ = r.Report(ctx) // Report logs errors; the next attempt stays four hours away.
197			retryAfter = time.Now().Add(pingInterval)
198		}
199	}
